# -*- coding: utf-8 -*-
"""Area silo page definitions: Service Areas hub + 12 city landing pages.
Local content is genuinely unique per city (per dev guides) — no templated swaps."""
import json
from build import (BASE, page_hero, local_context_section, table_section, area_services_section,
                   feature_section, prose_section, faq_section, cta_banner, map_section,
                   area_cards_section, area_localbusiness, breadcrumb, faqpage, collection_schema)

PAGES = []

def area_page(slug, city, title, desc, est_label, aeo, about_h2, profile, context,
              hoods, whys, climate_h2, climate, faq):
    url = f"{BASE}/{slug}/"
    crumbs_hero = [("Home", "/"), ("Service Areas", "/areas/"), (city, None)]
    crumbs_schema = [("Home", "/"), ("Service Areas", "/areas/"), (city, url)]
    return dict(
        slug=slug, title=title, description=desc, canonical=url,
        schemas=[area_localbusiness(city), breadcrumb(crumbs_schema), faqpage(faq)],
        body="\n\n".join([
            page_hero("Local Painting Services", f"Professional Painters in {city}, FL", aeo,
                      crumbs_hero, estimate_label=est_label),
            local_context_section(about_h2, profile, context, bg="cream"),
            table_section("Neighborhoods", f"Neighborhoods We Serve in {city}", None,
                          ["Neighborhood", "Housing Stock", "Painting Considerations"], hoods,
                          bg="white", anchor="hoods"),
            area_services_section(city, bg="cream"),
            feature_section("Why Choose Us", f"Why {city} Homeowners Choose Ayala Pro Painting", whys, bg="white"),
            prose_section("Local Climate", climate_h2, climate, bg="cream", anchor="climate"),
            faq_section(f"Painting Questions for {city} Homeowners", faq, bg="white"),
            cta_banner(f"Ready to Transform Your {city} Property?",
                       f"Get a free, no-obligation estimate from Riverview's trusted, locally owned painting professionals serving {city} and all of south Hillsborough County."),
        ]),
    )

